private function isBranchShopFrontCustomer(): bool
{
    $Customer = $this->getUser();
    if (!$Customer instanceof Customer) {
        return false;
    }
    $Player = $Customer->getPlayer();
    if ($Player === null) {
        return false;
    }

    return $Player->getCustomerGroup()->getBranchShopFrontFlg();
}
